-- Importa apenas a estrutura de colaboradores da ANADEM.
-- Referencia de origem: database/sql/reset_demo_anadem.sql
-- As credenciais importadas devem ser redefinidas apos o restore.

BEGIN;
SET TIME ZONE 'America/Sao_Paulo';

CREATE TEMP TABLE demo_collaborators (
    name text NOT NULL,
    email text NOT NULL,
    phone_raw text NULL,
    phone_digits text NULL,
    source_company text NULL,
    sector_name text NULL,
    sector_slug text NULL,
    gender text NULL,
    status_name text NOT NULL,
    is_active boolean NOT NULL
) ON COMMIT DROP;

INSERT INTO demo_collaborators (
    name,
    email,
    phone_raw,
    phone_digits,
    source_company,
    sector_name,
    sector_slug,
    gender,
    status_name,
    is_active
)
SELECT
    trim(payload.name),
    lower(trim(payload.email)),
    NULLIF(trim(COALESCE(payload.phone_raw, '')), ''),
    NULLIF(trim(COALESCE(payload.phone_digits, '')), ''),
    NULLIF(trim(COALESCE(payload.source_company, '')), ''),
    NULLIF(trim(COALESCE(payload.sector_name, '')), ''),
    NULLIF(trim(COALESCE(payload.sector_slug, '')), ''),
    NULLIF(trim(COALESCE(payload.gender, '')), ''),
    trim(payload.status_name),
    payload.is_active
FROM jsonb_to_recordset(
    convert_from(decode('', 'base64'), 'UTF8')::jsonb
) AS payload(
    name text,
    email text,
    phone_raw text,
    phone_digits text,
    source_company text,
    sector_name text,
    sector_slug text,
    gender text,
    status_name text,
    is_active boolean
);

CREATE TEMP TABLE demo_sector_defaults (
    slug text PRIMARY KEY,
    name text NOT NULL,
    color text NOT NULL,
    description text NOT NULL
) ON COMMIT DROP;

INSERT INTO demo_sector_defaults (slug, name, color, description)
