    ('administrativo-cirurgia-segura', 'Administrativo Cirurgia Segura', '#8D6E63', 'Setor demo importado da planilha de colaboradores com 2 colaborador(es).'),
    ('auditoria', 'AUDITORIA', '#C62828', 'Setor demo importado da planilha de colaboradores com 9 colaborador(es).'),
    ('carc', 'CARC', '#8E24AA', 'Setor demo importado da planilha de colaboradores com 4 colaborador(es).'),
    ('ceo-presidencia', 'CEO/PRESIDÊNCIA', '#1E3A8A', 'Setor demo importado da planilha de colaboradores com 3 colaborador(es).'),
    ('comercial', 'COMERCIAL', '#EF6C00', 'Setor demo importado da planilha de colaboradores com 6 colaborador(es).'),
    ('comercial-cirurgia-segura', 'Comercial Cirurgia Segura', '#FB8C00', 'Setor demo importado da planilha de colaboradores com 2 colaborador(es).'),
    ('compliance', 'COMPLIANCE', '#455A64', 'Setor demo importado da planilha de colaboradores com 2 colaborador(es).'),
    ('compras', 'COMPRAS', '#0F766E', 'Setor demo importado da planilha de colaboradores com 9 colaborador(es).'),
    ('comunicacao', 'COMUNICAÇÃO', '#D97706', 'Setor demo importado da planilha de colaboradores com 9 colaborador(es).'),
    ('contabilidade', 'CONTABILIDADE', '#0284C7', 'Setor demo importado da planilha de colaboradores com 2 colaborador(es).'),
    ('controladoria', 'CONTROLADORIA', '#7C3AED', 'Setor demo importado da planilha de colaboradores com 4 colaborador(es).'),
    ('financeiro', 'FINANCEIRO', '#0F9D58', 'Setor demo importado da planilha de colaboradores com 11 colaborador(es).'),
