    ('ti', 'TI', '#2563EB', 'Setor demo importado da planilha de colaboradores com 12 colaborador(es).');

CREATE TEMP TABLE collaborator_seed ON COMMIT DROP AS
SELECT DISTINCT ON (email)
    name,
    email,
    phone_raw,
    phone_digits,
    source_company,
    sector_name,
    sector_slug,
    gender,
    status_name,
    is_active
FROM demo_collaborators
ORDER BY
    email,
    CASE WHEN sector_slug IS NULL THEN 1 ELSE 0 END,
    CASE WHEN sector_name IS NULL THEN 1 ELSE 0 END,
    name;

CREATE TEMP TABLE sector_seed ON COMMIT DROP AS
SELECT
    collaborator.sector_slug AS slug,
    COALESCE(MAX(NULLIF(collaborator.sector_name, '')), MAX(defaults.name), collaborator.sector_slug) AS name,
    COALESCE(MAX(defaults.color), '#3D567B') AS color,
    COALESCE(
        MAX(defaults.description),
        format('Setor importado da carga de colaboradores com %s colaborador(es).', COUNT(*))
    ) AS description,
    COUNT(*) AS collaborator_count
FROM collaborator_seed AS collaborator
LEFT JOIN demo_sector_defaults AS defaults
    ON defaults.slug = collaborator.sector_slug
WHERE collaborator.sector_slug IS NOT NULL
GROUP BY collaborator.sector_slug;

CREATE TEMP TABLE seeded_company ON COMMIT DROP AS
WITH target_company AS (
    SELECT
        'ANADEM'::text AS name,
        'ANADEM S.A.'::text AS legal_name,
        '00.000.000/0001-00'::text AS document,
        'contato@anadem.com.br'::text AS email,
        '(61) 4000-0000'::text AS phone,
        true AS is_active
),
updated_company AS (
    UPDATE companies
    SET
        name = target_company.name,
        legal_name = target_company.legal_name,
        document = target_company.document,
        email = target_company.email,
        phone = target_company.phone,
        is_active = target_company.is_active,
        deleted_at = NULL,
        updated_at = now()
    FROM target_company
    WHERE companies.id = (
        SELECT company.id
        FROM companies AS company
        WHERE company.name = target_company.name
            OR company.legal_name = target_company.legal_name
        ORDER BY
            CASE WHEN company.deleted_at IS NULL THEN 0 ELSE 1 END,
            company.id
        LIMIT 1
    )
    RETURNING companies.id
),
inserted_company AS (
    INSERT INTO companies (
        name,
        legal_name,
        document,
        email,
        phone,
        is_active,
        created_at,
        updated_at
    )
    SELECT
        target_company.name,
        target_company.legal_name,
        target_company.document,
        target_company.email,
        target_company.phone,
        target_company.is_active,
        now(),
        now()
    FROM target_company
    WHERE NOT EXISTS (SELECT 1 FROM updated_company)
    RETURNING id
)
SELECT id FROM updated_company
UNION ALL
SELECT id FROM inserted_company;

INSERT INTO sectors (
    company_id,
    name,
    slug,
    color,
    description,
    is_active,
    created_at,
    updated_at
)
SELECT
    company.id,
    sector.name,
    sector.slug,
    sector.color,
    sector.description,
    true,
    now(),
    now()
FROM sector_seed AS sector
CROSS JOIN seeded_company AS company
ON CONFLICT (company_id, slug) DO UPDATE
SET
    name = EXCLUDED.name,
    color = EXCLUDED.color,
    description = EXCLUDED.description,
    is_active = EXCLUDED.is_active,
    deleted_at = NULL,
    updated_at = EXCLUDED.updated_at;

CREATE TEMP TABLE seeded_sectors ON COMMIT DROP AS
SELECT
    sector.id,
    sector.slug,
    sector.name
FROM sectors AS sector
CROSS JOIN seeded_company AS company
WHERE sector.company_id = company.id
    AND sector.slug IN (SELECT slug FROM sector_seed)
    AND sector.deleted_at IS NULL;

WITH ranked_collaborators AS (
    SELECT
        collaborator.*,
        ROW_NUMBER() OVER (ORDER BY collaborator.email) AS sequence_number
    FROM collaborator_seed AS collaborator
),
prepared_users AS (
    SELECT
        collaborator.name,
        collaborator.email,
        now() - INTERVAL '15 days' + (collaborator.sequence_number * INTERVAL '8 minutes') AS email_verified_at,
        '$2y$10$f94Q1.7IMxj0.DqExE75tOCWeO/oGRiJx5qds.hXYqx.TB2Ej0ZsC' AS password,
        CASE
            WHEN collaborator.email = 'admin@anadem.com.br' THEN 'super_admin'
            WHEN collaborator.email IN ('alisson.schimitz@aiatecnologia.com.br', 'adriel@anadem.org.br') THEN 'sector_admin'
            WHEN collaborator.email = 'adilio.silva@aiatecnologia.com.br' THEN 'technician'
            ELSE 'requester'
        END AS role,
        CASE
            WHEN collaborator.email = 'admin@anadem.com.br' THEN 'super_admin'
            ELSE 'collaborator'
        END AS global_role,
        seeded_sector.id AS sector_id,
        true AS must_change_password,
        collaborator.is_active,
        'light'::text AS theme_preference,
        now() - INTERVAL '20 days' + (collaborator.sequence_number * INTERVAL '8 minutes') AS created_at,
        now() - INTERVAL '20 days' + (collaborator.sequence_number * INTERVAL '8 minutes') AS updated_at
    FROM ranked_collaborators AS collaborator
    LEFT JOIN seeded_sectors AS seeded_sector
        ON seeded_sector.slug = collaborator.sector_slug
)
INSERT INTO users (
    name,
    email,
    email_verified_at,
    password,
    role,
    global_role,
    sector_id,
    room_id,
    must_change_password,
    is_active,
    theme_preference,
    created_at,
    updated_at
)
SELECT
    user_seed.name,
    user_seed.email,
    user_seed.email_verified_at,
    user_seed.password,
    user_seed.role,
    user_seed.global_role,
    user_seed.sector_id,
    NULL,
    user_seed.must_change_password,
    user_seed.is_active,
    user_seed.theme_preference,
    user_seed.created_at,
    user_seed.updated_at
FROM prepared_users AS user_seed
ON CONFLICT (email) DO UPDATE
SET
    name = EXCLUDED.name,
    email_verified_at = EXCLUDED.email_verified_at,
    password = EXCLUDED.password,
    role = EXCLUDED.role,
    global_role = EXCLUDED.global_role,
    sector_id = EXCLUDED.sector_id,
    room_id = EXCLUDED.room_id,
    must_change_password = EXCLUDED.must_change_password,
    is_active = EXCLUDED.is_active,
    theme_preference = EXCLUDED.theme_preference,
    deleted_at = NULL,
    updated_at = EXCLUDED.updated_at;

DELETE FROM user_sector_accesses AS access
USING users AS user_account,
      seeded_sectors AS sector
WHERE access.user_id = user_account.id
    AND access.sector_id = sector.id
    AND user_account.email IN (SELECT email FROM collaborator_seed)
    AND NOT EXISTS (
        SELECT 1
        FROM collaborator_seed AS collaborator
        WHERE collaborator.email = user_account.email
            AND collaborator.sector_slug = sector.slug
    );

INSERT INTO user_sector_accesses (
    user_id,
    sector_id,
    access_level,
    created_at,
    updated_at
)
SELECT
    user_account.id,
    sector.id,
    CASE
        WHEN user_account.email IN ('admin@anadem.com.br', 'alisson.schimitz@aiatecnologia.com.br', 'adriel@anadem.org.br') THEN 'sector_admin'
        WHEN user_account.email = 'adilio.silva@aiatecnologia.com.br' THEN 'technician'
        ELSE 'requester'
    END,
    now(),
    now()
FROM collaborator_seed AS collaborator
JOIN users AS user_account
    ON user_account.email = collaborator.email
JOIN seeded_sectors AS sector
    ON sector.slug = collaborator.sector_slug
WHERE collaborator.sector_slug IS NOT NULL
    AND user_account.deleted_at IS NULL
ON CONFLICT (user_id, sector_id) DO UPDATE
SET
    access_level = EXCLUDED.access_level,
    updated_at = EXCLUDED.updated_at;

DO $$
DECLARE
    expected_users integer;
    expected_users_without_sector integer;
    expected_sectors integer;
    expected_accesses integer;
    actual_company_count integer;
    actual_users integer;
    actual_users_without_sector integer;
    actual_sectors integer;
    actual_accesses integer;
    admin_role text;
    admin_global_role text;
BEGIN
    SELECT COUNT(*) INTO expected_users FROM collaborator_seed;
    SELECT COUNT(*) INTO expected_users_without_sector FROM collaborator_seed WHERE sector_slug IS NULL;
    SELECT COUNT(*) INTO expected_sectors FROM sector_seed;
    SELECT COUNT(*) INTO expected_accesses FROM collaborator_seed WHERE sector_slug IS NOT NULL;

    SELECT COUNT(*)
    INTO actual_company_count
    FROM companies
    WHERE name = 'ANADEM'
        AND deleted_at IS NULL;

    IF actual_company_count <> 1 THEN
        RAISE EXCEPTION 'Quantidade de empresas ANADEM ativa diferente do esperado. Atual: %, esperado: 1.', actual_company_count;
    END IF;

    SELECT COUNT(*)
    INTO actual_users
    FROM users
    WHERE email IN (SELECT email FROM collaborator_seed)
        AND deleted_at IS NULL;

    IF actual_users <> expected_users THEN
        RAISE EXCEPTION 'Quantidade de usuarios importados diferente do esperado. Atual: %, esperado: %.', actual_users, expected_users;
    END IF;

    SELECT COUNT(*)
    INTO actual_users_without_sector
    FROM users
    WHERE email IN (
            SELECT email
            FROM collaborator_seed
            WHERE sector_slug IS NULL
        )
        AND sector_id IS NULL
        AND deleted_at IS NULL;

    IF actual_users_without_sector <> expected_users_without_sector THEN
        RAISE EXCEPTION 'Quantidade de usuarios sem setor diferente do esperado. Atual: %, esperado: %.', actual_users_without_sector, expected_users_without_sector;
    END IF;

    SELECT COUNT(*)
    INTO actual_sectors
    FROM sectors AS sector
    CROSS JOIN seeded_company AS company
    WHERE sector.company_id = company.id
        AND sector.slug IN (SELECT slug FROM sector_seed)
        AND sector.deleted_at IS NULL;

    IF actual_sectors <> expected_sectors THEN
        RAISE EXCEPTION 'Quantidade de setores ANADEM diferente do esperado. Atual: %, esperado: %.', actual_sectors, expected_sectors;
    END IF;

    SELECT COUNT(*)
    INTO actual_accesses
    FROM user_sector_accesses AS access
    JOIN users AS user_account
        ON user_account.id = access.user_id
    JOIN seeded_sectors AS sector
        ON sector.id = access.sector_id
    WHERE user_account.email IN (SELECT email FROM collaborator_seed)
        AND user_account.deleted_at IS NULL;

    IF actual_accesses <> expected_accesses THEN
        RAISE EXCEPTION 'Quantidade de acessos setoriais diferente do esperado. Atual: %, esperado: %.', actual_accesses, expected_accesses;
    END IF;

    SELECT role, global_role
    INTO admin_role, admin_global_role
    FROM users
    WHERE email = 'admin@anadem.com.br'
        AND deleted_at IS NULL
    LIMIT 1;

    IF admin_role IS DISTINCT FROM 'super_admin' OR admin_global_role IS DISTINCT FROM 'super_admin' THEN
        RAISE EXCEPTION 'Usuario admin@anadem.com.br nao ficou com perfil super_admin/super_admin. Atual: % / %.', admin_role, admin_global_role;
    END IF;
END $$;

SELECT
    (SELECT COUNT(*) FROM companies WHERE name = 'ANADEM' AND deleted_at IS NULL) AS active_anadem_companies,
    (SELECT COUNT(*) FROM sectors AS sector CROSS JOIN seeded_company AS company WHERE sector.company_id = company.id AND sector.deleted_at IS NULL) AS active_anadem_sectors,
    (SELECT COUNT(*) FROM users WHERE email IN (SELECT email FROM collaborator_seed) AND deleted_at IS NULL) AS imported_users,
    (SELECT COUNT(*) FROM users WHERE email IN (SELECT email FROM collaborator_seed) AND deleted_at IS NULL AND is_active = true) AS imported_users_active,
    (SELECT COUNT(*) FROM users WHERE email IN (SELECT email FROM collaborator_seed) AND deleted_at IS NULL AND is_active = false) AS imported_users_inactive,
    (SELECT COUNT(*) FROM users WHERE email IN (SELECT email FROM collaborator_seed) AND deleted_at IS NULL AND sector_id IS NULL) AS imported_users_without_sector,
    (SELECT COUNT(*) FROM user_sector_accesses AS access JOIN users AS user_account ON user_account.id = access.user_id WHERE user_account.email IN (SELECT email FROM collaborator_seed) AND user_account.deleted_at IS NULL) AS imported_sector_accesses;

COMMIT;
